import { processAudio } from '008Q';

const qworkerLLM = new Worker(new URL('./Q008WorkerLLM.js', import.meta.url), {
  type: 'module'
});

const qworkerTTS = new Worker(new URL('./Q008WorkerTTS.js', import.meta.url), {
  type: 'module'
});

export const transcribe = async ({ id, chunksLocal, chunksRemote }) => {
  return new Promise(async (resolve, reject) => {
    const wav = async input => (await processAudio({ input })).wav;
    
    const remote = await wav(chunksRemote);
    const local = await wav(chunksLocal);

    const handleMessage = ({ data }) => {
      if (data.id === id) {
        qworkerTTS.removeEventListener('message', handleMessage);
        
        if (data.error) 
          reject(new Error(data.error));
        else 
          resolve(data);
      }
    };

    qworkerTTS.addEventListener('message', handleMessage);
    qworkerTTS.postMessage({ id, audio: { remote, local } });
  });
};

export const summarize = async ({ id, transcription }) => {
  return new Promise(async (resolve, reject) => {
    const handleMessage = ({ data }) => {
      if (data.id === id) {
        qworkerLLM.removeEventListener('message', handleMessage);
        
        if (data.error) 
          reject(new Error(data.error));
        else 
          resolve(data);
      }
    };

    qworkerLLM.addEventListener('message', handleMessage);
    qworkerLLM.postMessage({ id, transcription });
  });
};
