import { create } from 'zustand';
import {
  persist,
  createJSONStorage,
  subscribeWithSelector
} from 'zustand/middleware';

import AsyncStorage from "@react-native-async-storage/async-storage";
import { encode } from 'base-64';

import contacts from './Contacts';
import { isWeb } from '../utils';

const localStorage = isWeb ? global.localStorage : AsyncStorage;
const STOR_ID = 'OO8Store.v1.4';
const LOGIN_URI = 'http://192.168.5.87:1008/settings';
const CDRS_MAX = 100;
const EVENTS_MAX = 100;

const DEFAULTS_NOCONFIG = {
  size: { width: 340, height: 460 },

  anchored: true,
  doquit: false,
  electron: false,

  status: 'online',
  online: false,

  number_out: undefined,

  notificationToken: undefined,
  voipToken: undefined,

  devices: [],
  microphones: [],
  ringer: 'default',
  speaker: 'default',
  microphone: 'default',

  cdrs: [],

  events: [],
  qTts: true,
  qSummarization: false,

  session: undefined,
  sessiont: undefined,
};

const DEFAULTS = {
  name: '008 Phone',

  settingsUri: undefined,
  authToken: undefined,
  nickname: undefined,
  avatar: undefined,

  sipUser: undefined,
  sipPassword: undefined,
  sipUri: undefined,
  wsUri: undefined,
  rtcConfiguration: undefined,

  numbers: [], 
  number_out: undefined,

  statuses: [
    { "value": "online", "text": "Online", "color": "#057e74" },
    { "value": "offline", "text": "Offline", "color": "#A9A9A9" }
  ], 

  allowTransfer: true,
  allowBlindTransfer: true,
  allowVideo: true,

  autoanswer: 0,

  webhooks: [],
}

export const useStore = create(
  persist(
    subscribeWithSelector((set, get) => ({
    ...DEFAULTS_NOCONFIG,
    ...DEFAULTS,

    setState: state => set(() => ({ ...state })),

    login: async ({ settingsUri, authToken }) => {
      if (!settingsUri) throw new Error(`No settings uri available!`);

      let headers = {
        'Content-Type': 'application/json',
      };

      if (authToken) {
        headers = { ...headers, Authorization: authToken };
      }

      let response;

      if (!/^(https?|file):\/\//i.test(settingsUri)) {
        try {
          response = await fetch(`file://${settingsUri}`, {
            method: 'GET',
            headers
          });
        } catch (err) {
          console.error(err);
        }
      }

      if (!response?.ok) {
        response = await fetch(settingsUri, {
          method: 'GET',
          headers
        });

        if (!response.ok)
          throw new Error(`HTTP status: ${response.status}`);
      }

      const settings = await response.json();
      const { number_out, numbers = [] } = settings;
      if (!number_out) {
        settings.number_out = numbers[0]?.name || '';
      }

      set(() => ({
        ...DEFAULTS,
        ...settings,
        settingsUri,
        authToken
      }));
    },

    loginManaged: async ({ nickname, password }) => {
      const settingsUri = LOGIN_URI;
      const authToken = `Basic: ${encode(`${nickname}:${password}`)}`;
      return get().login({ settingsUri, authToken });
    },

    cdrAdd: cdr => {
      const { cdrs } = get();
      const { headers, ...rest } = cdr;
      cdrs.unshift(rest);
      set(() => ({ cdrs: cdrs.slice(0, CDRS_MAX) }));
    },

    eventAdd: event => {
      const { events } = get();
      const { data, type } = event; 
      const { audio, ...rest } = data;

      events.unshift({ type, data: rest });
      set(() => ({ events: events.slice(0, EVENTS_MAX) }));
    },

    clear: () => {
      localStorage.clear();
      contacts.clear();

      set(() => ({ ...DEFAULTS, cdrs: [], events: [] }));
    }
  })),
  {
    name: STOR_ID,
    storage: createJSONStorage(() => localStorage),
    partialize: ({
      name,
      session,
      sessiont,
      online,

      doquit,
      electron,

      ...rest
    }) => ({ ...rest })
  })
);
