import { useState } from 'react';
import { ApplicationInsights } from '@microsoft/applicationinsights-web';
import {
  AppInsightsErrorBoundary,
  ReactPlugin
} from '@microsoft/applicationinsights-react-js';

import { VPhone } from './phone/VPhone';
import Phone from './components/Phone';

VPhone.init();

const connectionString = 'InstrumentationKey=89ba4ad2-47ef-41e8-a151-4b3488132c63;IngestionEndpoint=https://westeurope-5.in.applicationinsights.azure.com/;LiveEndpoint=https://westeurope.livediagnostics.monitor.azure.com/';
const reactPlugin = new ReactPlugin();
const appInsights = new ApplicationInsights({
  config: {
    connectionString,
    extensions: [reactPlugin]
  }
});
appInsights.loadAppInsights();
appInsights.trackPageView();

export function App() {
  const [key, setKey] = useState(0);
  const reset = () => {
    VPhone.handleException();
    setKey(key + 1);
  };

  return (
    <AppInsightsErrorBoundary 
      appInsights={reactPlugin}
      onError={reset}
      key={key}
    >
      <Phone />
    </AppInsightsErrorBoundary>
  );
}
